#include "tool_registry.hpp"
#include <cmath>
namespace g9 {
void ToolRegistry::add(ToolDefinition d,ToolPreflight p,ToolExecutor e){entries_.push_back({std::move(d),std::move(p),std::move(e)});} std::vector<ToolDefinition> ToolRegistry::definitions()const{std::vector<ToolDefinition> o;for(auto&e:entries_)o.push_back(e.definition);return o;} const ToolDefinition* ToolRegistry::definition(std::string_view n)const{for(auto&e:entries_)if(e.definition.name==n)return &e.definition;return nullptr;}
bool ToolRegistry::validate(const ToolDefinition& d,const JsonValue& a,std::string& err)const{if(!a.is_object()){err="arguments must be object";return false;}if(!d.input_schema.is_object())return true;auto&s=d.input_schema.as_object();if(auto*r=object_get(s,"required");r&&r->is_array())for(auto&k:r->as_array()){if(!k.is_string())continue;if(!a.as_object().contains(k.as_string())){err="missing required argument: "+k.as_string();return false;}}if(auto*p=object_get(s,"properties");p&&p->is_object()){for(auto&[k,v]:a.as_object()){auto it=p->as_object().find(k);if(it==p->as_object().end()){if(auto*ap=object_get(s,"additionalProperties");ap&&ap->is_bool()&&!ap->as_bool()){err="unexpected argument: "+k;return false;}continue;}if(it->second.is_object()){auto*t=object_get(it->second.as_object(),"type");if(t&&t->is_string()){auto ty=t->as_string();bool ok=ty=="string"?v.is_string():ty=="boolean"?v.is_bool():ty=="number"?v.is_number():ty=="integer"?(v.is_number()&&std::floor(v.as_number())==v.as_number()):ty=="array"?v.is_array():ty=="object"?v.is_object():true;if(!ok){err="wrong type for argument: "+k;return false;}}}}}return true;}
ToolResult ToolRegistry::execute(const ToolCall& c,bool approved)const{for(auto&e:entries_)if(e.definition.name==c.name){std::string err;if(!validate(e.definition,c.arguments,err))return{ToolDisposition::failed,false,JsonValue::object{{"error",err}},err,{}};ActionDescriptor a;try{a=e.preflight(c.arguments);}catch(const std::exception&x){return{ToolDisposition::failed,false,JsonValue::object{{"error",x.what()}},x.what(),{}};}auto dec=guardrails_.decide(a);if(dec.action==PolicyAction::deny)return{ToolDisposition::denied,false,JsonValue::object{{"error",dec.reason}},dec.reason,a};if(dec.action==PolicyAction::ask&&!approved)return{ToolDisposition::approval_required,false,JsonValue::object{{"approval_required",true}},dec.reason,a};try{return e.executor(c.arguments);}catch(const std::exception&x){return{ToolDisposition::failed,false,JsonValue::object{{"error",x.what()}},x.what(),{}};}}return{ToolDisposition::failed,false,JsonValue::object{{"error","unknown tool"}},"unknown tool",{}};}
std::string to_string(ToolDisposition d){switch(d){case ToolDisposition::completed:return"completed";case ToolDisposition::approval_required:return"approval_required";case ToolDisposition::denied:return"denied";case ToolDisposition::failed:return"failed";}return"failed";}
} // namespace g9
